// Direct Worker only: no static-assets router or service-binding entrypoint.
// Trusted Access identity: https://developers.cloudflare.com/workers/configuration/cloudflare-access/
// Private object reads: https://developers.cloudflare.com/r2/api/workers/workers-api-reference/
// Client routes read only. Operator-only release writes use the separate bridge.
import { handleAdminRequest, handleDraftAutomationRequest, validateReleaseIndex } from './release-admin.mjs';
import { handleAdminStatus, handleDraftStatus, handleDraftDownload } from './admin-status.mjs';
import { ReleaseTree, ReleasePageError, validateReleaseRoot, parseRelease, releaseCursor, readReleaseCursor } from './release-pages.mjs';
import { visibleReleasePage, issueProjection, visibleRelease } from './release-history.mjs';
const INDEX_LIMIT = 512 * 1024;
const FILE_LIMIT = 32 * 1024 * 1024;
const ID = /^[a-zA-Z0-9][a-zA-Z0-9_-]{0,95}$/;
const HASH = /^[a-f0-9]{64}$/;
const PAGE_REDIRECTS = Object.freeze({
  '/': '/reports',
  '/archive': '/reports/archive',
  '/reports/': '/reports',
  '/reports/archive/': '/reports/archive',
});
// Original approved logo, embedded so no public asset route is needed.
const BRAND_LOGO = 'data:image/png;base64,';
const TYPES = {
  pdf: 'application/pdf',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
};
const SECURITY = {
  'Cache-Control': 'private, no-store, max-age=0',
  'Vary': 'Cookie',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
  'Content-Security-Policy': "default-src 'none'; img-src data:; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
};

function response(body, status = 200, type = 'text/plain; charset=utf-8', head = false, extra = {}) {
  return new Response(head ? null : body, { status, headers: { ...SECURITY, 'Content-Type': type, ...extra } });
}

function config(env) {
  if (!ID.test(env.CLIENT_ID ?? '') || !env.ACCESS_AUD?.trim() || !env.REPORTS?.get) throw new Error('configuration');
  const emails = JSON.parse(env.ALLOWED_EMAILS);
  // An explicitly empty client list is an owner-only setup, not public access.
  if (!Array.isArray(emails) || emails.length > 20 || emails.some(email => typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))) {
    throw new Error('configuration');
  }
  const operators = JSON.parse(env.OPERATOR_EMAILS);
  if (!Array.isArray(operators) || !operators.length || operators.length > 20 ||
    operators.some(email => typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) ||
    operators.some(operator => emails.some(email => email.toLowerCase() === operator.toLowerCase()))) {
    throw new Error('configuration');
  }
  return { client: env.CLIENT_ID, aud: env.ACCESS_AUD, emails: new Set(emails.map(email => email.toLowerCase())) };
}

function instant(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,3})?(?:Z|\+00:00)$/.test(value)) throw new Error('date');
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed) || new Date(parsed).toISOString().slice(0, 19) !== value.slice(0, 19)) throw new Error('date');
  return parsed;
}

function safeText(value, limit) {
  return typeof value === 'string' && value.length <= limit && !/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(value);
}

function objectPrefix(client, issue, revision) {
  return `clients/${client}/issues/${issue}/r${revision}/`;
}

export function validateIndex(index, client) {
  if (!index || index.schema_version !== 1 || index.client_id !== client || !Array.isArray(index.issues) || index.issues.length > 500) throw new Error('index');
  const revisions = new Set(), active = new Set();
  for (const issue of index.issues) {
    if (!issue || !ID.test(issue.issue_id ?? '') || !Number.isSafeInteger(issue.revision) || issue.revision < 1 ||
        !['active', 'withdrawn'].includes(issue.remote_state) || typeof issue.approved !== 'boolean' || typeof issue.complete !== 'boolean' ||
        !Number.isSafeInteger(issue.product_count) || issue.product_count < 0 || issue.product_count > 20 ||
        !Number.isSafeInteger(issue.new_count) || issue.new_count < 0 || issue.new_count > issue.product_count ||
        !safeText(issue.title, 160) || !issue.title.trim() || (issue.summary !== undefined && !safeText(issue.summary, 1600)) ||
        !HASH.test(issue.package_hash ?? '') || !Array.isArray(issue.files) || issue.files.length > 3 ||
        !Array.isArray(issue.languages) || issue.languages.length > 2 || new Set(issue.languages).size !== issue.languages.length ||
        issue.languages.some(language => !['en', 'hi-Latn'].includes(language)) ||
        !(issue.publication_ordinal === null || (Number.isSafeInteger(issue.publication_ordinal) && issue.publication_ordinal > 0))) throw new Error('issue');
    instant(issue.scheduled_at);
    instant(issue.server_activated_at);
    const identity = `${issue.issue_id}:${issue.revision}`;
    if (revisions.has(identity)) throw new Error('revision');
    revisions.add(identity);
    if (issue.remote_state === 'active') {
      if (active.has(issue.issue_id)) throw new Error('revision');
      active.add(issue.issue_id);
    }
    const names = new Set();
    const expectedNames = new Set(['shortlist.xlsx', ...issue.languages.map(language => `report-${language}.pdf`)]);
    for (const file of issue.files) {
      const extension = typeof file?.name === 'string' ? file.name.split('.').at(-1) : undefined;
      if (!file || !expectedNames.has(file.name) || !TYPES[extension] || file.media_type !== TYPES[extension] ||
          file.key !== objectPrefix(client, issue.issue_id, issue.revision) + file.name || !HASH.test(file.sha256 ?? '') ||
          !Number.isSafeInteger(file.size) || file.size < 1 || file.size > FILE_LIMIT || names.has(file.name)) throw new Error('file');
      names.add(file.name);
    }
    if (issue.complete && (issue.publication_ordinal === null || issue.languages.length < 1 || names.size !== expectedNames.size ||
        (issue.publication_ordinal <= 2 ? issue.languages.length !== 2 : issue.languages.length !== 1))) throw new Error('file');
  }
  return index;
}

function released(issue, now) {
  return issue.remote_state === 'active' && issue.approved === true && issue.complete === true && issue.product_count >= 10 &&
    issue.new_count * 5 >= issue.product_count * 4 && instant(issue.scheduled_at) <= now && instant(issue.server_activated_at) <= now;
}

async function readBytes(object, limit, size) {
  if (!object || !Number.isSafeInteger(object.size) || object.size < 1 || object.size > limit ||
      (size !== undefined && object.size !== size) || typeof object.arrayBuffer !== 'function') throw new Error('object');
  const bytes = await object.arrayBuffer();
  if (bytes.byteLength !== object.size || bytes.byteLength > limit) throw new Error('object');
  return bytes;
}

function escape(value) {
  return String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

function downloadUrl(issue, file) {
  return `/reports/download/${encodeURIComponent(issue.issue_id)}/${issue.revision}/${encodeURIComponent(file.name)}`;
}

function issueHtml(issue, latest = false) {
  const date = new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Asia/Kolkata' }).format(new Date(issue.scheduled_at));
  const downloads = issue.files.map(file => {
    const format = file.name.endsWith('.pdf') ? 'PDF' : 'Excel';
    const language = file.name.endsWith('.xlsx') ? '' : file.name === 'report-hi-Latn.pdf' ? 'Hinglish' : 'English';
    return `<a class="download" href="${escape(downloadUrl(issue, file))}">Download ${format}${language ? `<span>${language}</span>` : ''}</a>`;
  }).join('');
  return `<article class="issue${latest ? ' latest' : ''}"><p class="date">${escape(date)} · ${issue.product_count} products</p><h${latest ? '1' : '2'}>${escape(issue.title)}</h${latest ? '1' : '2'}>${issue.summary ? `<p class="summary">${escape(issue.summary)}</p>` : ''}<div class="downloads">${downloads}</div></article>`;
}

function page(issues, archive) {
  const content = archive ? `<h1>Earlier reports</h1>${issues.map(issue => issueHtml(issue)).join('') || '<p class="empty">Your reports will appear here after release.</p>'}` :
    issues.length ? `<p class="section">Latest report</p>${issueHtml(issues[0], true)}` : '<h1>Your next report</h1><p class="empty">Your report will appear here when it is ready.</p>';
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${archive ? 'Earlier reports' : 'Product reports'} · NeuraFlow</title><style>
  :root{color-scheme:light;--cream:#F9F3EC;--maroon:#6B1F2B;--ink:#253540;--muted:#636862;--line:#dcd3c8;--sage:#e5e9df}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:17px/1.6 Arial,sans-serif}a{color:var(--maroon)}a:focus-visible{outline:3px solid var(--maroon);outline-offset:5px}header,main,footer{max-width:820px;margin:auto;padding:28px 28px}header{display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--line)}.brand{display:block;width:172px;height:48px;overflow:hidden}.brand img{display:block;width:172px;height:86px;margin-top:-14px}nav{display:flex;gap:22px;font-size:15px}nav a{text-decoration:none}nav a[aria-current=page]{text-decoration:underline;text-underline-offset:5px}main{padding-top:48px;padding-bottom:64px;min-height:65vh}h1,h2{overflow-wrap:anywhere;font:normal 40px/1.2 Georgia,serif;letter-spacing:-.7px;margin:12px 0 22px}h2{font-size:28px}.section,.date{font-size:15px;color:var(--muted);margin:0}.section{margin-bottom:24px}.summary{overflow-wrap:anywhere;max-width:64ch;white-space:pre-line;margin-bottom:28px}.issue{padding:28px 0;border-bottom:1px solid var(--line)}.latest{padding:0;border:0}.downloads{display:flex;flex-wrap:wrap;gap:12px}.download{display:flex;align-items:center;justify-content:space-between;gap:20px;min-width:225px;padding:12px 16px;background:var(--sage);text-decoration:none}.download:hover{background:#dce1d5}.download span{font-size:14px;color:var(--muted)}footer{font-size:14px;color:var(--muted);border-top:1px solid var(--line)}.empty{max-width:42ch;color:var(--muted)}@media(max-width:520px){header,main,footer{padding-left:20px;padding-right:20px}header{align-items:flex-start;gap:18px;flex-direction:column;padding-top:24px;padding-bottom:22px}main{padding-top:36px}h1{font-size:34px}h2{font-size:27px}.downloads{display:grid;grid-template-columns:1fr}.download{min-width:0}nav{gap:26px}}
  </style></head><body><header><a class="brand" href="/reports" aria-label="NeuraFlow latest report"><img src="${BRAND_LOGO}" alt="NeuraFlow" width="172" height="86"></a><nav aria-label="Reports"><a href="/reports"${!archive ? ' aria-current="page"' : ''}>Latest report</a><a href="/reports/archive"${archive ? ' aria-current="page"' : ''}>Earlier reports</a></nav></header><main>${content}</main><footer>Product research, made easier.</footer></body></html>`;
}

export async function handleRequest(request, env, ctx, now = Date.now()) {
  if (new URL(request.url).pathname.startsWith('/_automation/drafts/')) return handleDraftAutomationRequest(request, env, ctx);
  if (['/admin/drafts', '/admin/drafts/'].includes(new URL(request.url).pathname)) return handleDraftStatus(request, env, ctx, BRAND_LOGO);
  if (new URL(request.url).pathname.startsWith('/admin/download/')) return handleDraftDownload(request, env, ctx);
  if (['/admin', '/admin/'].includes(new URL(request.url).pathname)) return handleAdminStatus(request, env, ctx, BRAND_LOGO);
  if (new URL(request.url).pathname.startsWith('/admin/')) return handleAdminRequest(request, env, ctx);
  const head = request.method === 'HEAD';
  let settings;
  try { settings = config(env); } catch { return response('Service unavailable.', 503, undefined, head); }
  // Header claims and cookies are not identity. Only Cloudflare's authenticated context is trusted.
  if (!ctx?.access || ctx.access.aud !== settings.aud || typeof ctx.access.getIdentity !== 'function') return response('Access required.', 403, undefined, head);
  try {
    const identity = await ctx.access.getIdentity();
    if (typeof identity?.email !== 'string' || !settings.emails.has(identity.email.toLowerCase())) return response('Access required.', 403, undefined, head);
  } catch { return response('Access required.', 403, undefined, head); }
  if (!['GET', 'HEAD'].includes(request.method)) return response('Method not allowed.', 405, undefined, head, { Allow: 'GET, HEAD' });
  try {
    const url = new URL(request.url);
    const route = url.pathname;
    // Authentication and allowed-method checks above also protect redirects.
    if (PAGE_REDIRECTS[route]) return response('', 308, undefined, head, { Location: PAGE_REDIRECTS[route] + url.search });
    // Keep old, already-shared download URLs usable with identical access/release checks.
    const match = /^\/(?:reports\/)?download\/([a-zA-Z0-9_-]+)\/([1-9]\d*)\/([a-zA-Z0-9._-]+)$/.exec(route);
    if (!['/reports', '/reports/archive'].includes(route) && !match) return response('Not found.', 404, undefined, head);
    const stored = await env.REPORTS.get(`clients/${settings.client}/release-index.json`);
    const rawBytes = stored ? new Uint8Array(await readBytes(stored, INDEX_LIMIT)) : null;
    const rawIndex = rawBytes ? JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(rawBytes)) : null;
    if (rawIndex?.schema_version === 2) {
      const at = new Date(now).toISOString(), root = validateReleaseRoot(parseRelease(rawBytes), settings.client, at), tree = new ReleaseTree(env.REPORTS, root);
      const validateEntry = (entry, observed) => validateReleaseIndex({ schema_version: 1, client_id: settings.client, issues: [entry] }, settings.client, observed);
      if (match) {
        if (url.search) return response('Not found.', 404, undefined, head);
        const selected = await issueProjection(tree, match[1], validateEntry, at), issue = selected?.active;
        const file = issue?.revision === Number(match[2]) && visibleRelease(issue, at) ? issue.files.find(item => item.name === match[3]) : null;
        if (!file) return response('Not found.', 404, undefined, head);
        const bytes = await readBytes(await env.REPORTS.get(file.key), FILE_LIMIT, file.size);
        const digest = [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(v => v.toString(16).padStart(2, '0')).join('');
        if (digest !== file.sha256) throw new Error('integrity');
        return response(bytes, 200, file.media_type, head, { 'Content-Disposition': `attachment; filename="${file.name}"`, 'Content-Length': String(file.size) });
      }
      if ([...url.searchParams.keys()].some(key => key !== 'cursor') || url.searchParams.getAll('cursor').length > 1 || route === '/reports' && url.search) return response('Not found.', 404, undefined, head);
      const cursor = url.searchParams.get('cursor'), position = cursor === null ? null : await readReleaseCursor(cursor, root, 'timeline');
      if (position && (position.reverse !== true || position.prefix !== '')) throw new ReleasePageError('RELEASE_CURSOR_INVALID', 400);
      const result = await visibleReleasePage(tree, { after: position?.last_key ?? null, limit: route === '/reports' ? 1 : 20, at, validateEntry });
      const next = result.more ? await releaseCursor(root, 'timeline', result.last_key, { reverse: true, prefix: '' }) : null;
      // A cursor only navigates this client's current, verified tree. It never
      // supplies an object key, release decision or substitute authority.
      const html = page(result.entries, route === '/reports/archive', next).replace('</main>', `${next === null ? '' : `<p><a href="/reports/archive?cursor=${escape(next)}">More earlier reports</a></p>`}</main>`);
      return response(html, 200, 'text/html; charset=utf-8', head);
    }
    const index = rawIndex ? validateIndex(rawIndex, settings.client) : { issues: [] };
    const visible = index.issues.filter(issue => released(issue, now)).sort((a, b) => instant(b.scheduled_at) - instant(a.scheduled_at) || b.revision - a.revision || a.issue_id.localeCompare(b.issue_id));
    if (!match) return response(page(visible, route === '/reports/archive'), 200, 'text/html; charset=utf-8', head);
    const issue = visible.find(item => item.issue_id === match[1] && item.revision === Number(match[2]));
    const file = issue?.files.find(item => item.name === match[3]);
    // Release/approval check happens before any artifact read, even for guessed direct URLs.
    if (!file) return response('Not found.', 404, undefined, head);
    const bytes = await readBytes(await env.REPORTS.get(file.key), FILE_LIMIT, file.size);
    const hash = [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(value => value.toString(16).padStart(2, '0')).join('');
    if (hash !== file.sha256) throw new Error('integrity');
    return response(bytes, 200, file.media_type, head, { 'Content-Disposition': `attachment; filename="${file.name}"`, 'Content-Length': String(file.size) });
  } catch (error) { return response(error instanceof ReleasePageError && error.status === 409 ? 'The report list changed. Please open Earlier reports again.' : 'Report temporarily unavailable.',
    error instanceof ReleasePageError ? error.status : 503, undefined, head); }
}

export default { fetch(request, env, ctx) { return handleRequest(request, env, ctx); } };
